def sieve(limit):
    is_prime = bytearray([1]) * (limit + 1)
    is_prime[0] = 0
    is_prime[1] = 0
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, limit+1, i):
                is_prime[j] = 0
    return [i for i, v in enumerate(is_prime) if v]

primes = sieve(100000)

rows = [4123, 818, 4562, 1454, 2430, 5575, 2968, 1526, 5318, 5495, 3586, 2337, 832, 3283, 5659, 3818, 4386, 2490, 4603, 3316]

for i, n in enumerate(rows, 1):
